impl<'a> Direct<'a> {
    pub fn as_parse_tree(&'a self) -> ParseTree<'a> {
        ParseTree::Direct(self)
    }
    pub(crate) fn child(&self, index: usize) -> Option<ParseTree<'a>> {
        match self {
            Direct::C1 { direct, .. } => match index {
                0 => Some(ParseTree::Direct(direct)),
                _ => None,
            },
            Direct::C2 { lit_0, .. } => match index {
                0 => Some(ParseTree::Token(*lit_0)),
                _ => None,
            },
            Direct::Amb(alts) => alts.get(index).copied(),
            Direct::Cycle { .. } => None,
        }
    }
    pub(crate) fn child_count(&self) -> usize {
        match self {
            Direct::C1 { .. } => 1usize,
            Direct::C2 { .. } => 1usize,
            Direct::Amb(alts) => alts.len(),
            Direct::Cycle { .. } => 0,
        }
    }
    pub fn span(&self) -> Span {
        match self {
            Direct::C1 { span, .. } => *span,
            Direct::C2 { span, .. } => *span,
            Direct::Amb(alts) => alts[0].span(),
            Direct::Cycle { target } => target.get().span(),
        }
    }
    pub fn display_name(&self) -> &'static str {
        match self {
            Direct::Amb(_) => "Amb",
            Direct::Cycle { .. } => "Cycle",
            _ => "Direct",
        }
    }
    pub fn origin(&self) -> Option<Origin> {
        None
    }
}
